-- Correggi geometrie non valide prodotte dal clipping
UPDATE public.map_sectors
  SET geometry = ST_Multi(ST_CollectionExtract(ST_MakeValid(geometry), 3))
  WHERE service_type = 'd2d'
    AND NOT ST_IsValid(geometry)
    AND municipality_code IN ('020001', '020002', '020003', '020007', '020008', '020010', '020011', '020012', '020013', '020014', '020015', '020016', '020017', '020018', '020019', '020020', '020021', '020022', '020024', '020025', '020026', '020027', '020028', '020029', '020030', '020031', '020032', '020033', '020034', '020035', '020036', '020037', '020038', '020039', '020041', '020042', '020043', '020044', '020045', '020046', '020047', '020048', '020050', '020051', '020052', '020053', '020054', '020055', '020056', '020057', '020058', '020059', '020060', '020061', '020062', '020063', '020064', '020065', '020066', '020068', '020070', '020071', '020072', '020073');

